import { createContext, useContext } from 'react';
import type { AvatarGroupContextProps } from './types';

export const AvatarGroupContext = createContext<AvatarGroupContextProps | undefined>(undefined);

export const useAvatarGroup = (): AvatarGroupContextProps | undefined => {
    // It's okay for this to be undefined if an Avatar is not inside an AvatarGroup
    const context = useContext(AvatarGroupContext);
    if (context === undefined) {
        // console.warn('useAvatarGroup hook used outside of AvatarGroupContext.Provider');
    }
    return context;
};