import type { ColorShade, ThemeColors } from '@crossbuildui/core';
import { Text, useTheme } from '@crossbuildui/core'; // Adjust path
import { BlurView } from 'expo-blur';
import React, { useMemo, useState } from 'react';
import { Image, ImageErrorEventData, ImageSourcePropType, NativeSyntheticEvent, Platform, StyleSheet, View } from 'react-native';
import { useAvatarGroup } from './AvatarGroupContext';
import AvatarIcon from './AvatarIcon'; // Default fallback icon
import type { AvatarProps, AvatarSize } from './types';

const getInitials = (name?: string): string => {
    if (!name) return '';
    const names = name.trim().split(' ');
    if (names.length === 1 && names[0]) return names[0][0].toUpperCase();
    if (names.length > 1 && names[0] && names[names.length - 1]) {
        return `${names[0][0]}${names[names.length - 1][0]}`.toUpperCase();
    }
    return '';
};

const Avatar: React.FC<AvatarProps> = ({
    src,
    name,
    icon,
    fallback,
    color: propColor,
    size: propSize,
    radius: propRadius,
    isBordered: propIsBordered,
    isDisabled: propIsDisabled,
    showFallback = true,
    imgProps,
    ImgComponent = Image,
    styles: customSlotsStyles,
    style,
    isGlass: propIsGlass,
    glassTint: propGlassTint,
    glassIntensity: propGlassIntensity = 50,
    onError,
}) => {
    const { colors: themeColors, layout: layoutConfig, mode } = useTheme();
    const groupContext = useAvatarGroup();

    const [imageError, setImageError] = useState(false);

    const color = propColor || groupContext?.color || 'default';
    const size = propSize || groupContext?.size || 'md';
    const radius = propRadius || groupContext?.radius || 'full';
    const isBordered = propIsBordered !== undefined ? propIsBordered : groupContext?.isBordered || false;
    const isDisabled = propIsDisabled !== undefined ? propIsDisabled : groupContext?.isDisabled || false;
    const isGlass = propIsGlass !== undefined ? propIsGlass : groupContext?.isGlass || false;
    const glassTint = propGlassTint !== undefined ? propGlassTint : groupContext?.glassTint;
    const glassIntensity = propGlassIntensity !== undefined ? propGlassIntensity : groupContext?.glassIntensity || 50;

    const handleImageError = (event: NativeSyntheticEvent<ImageErrorEventData>) => {
        setImageError(true);
        if (onError) {
            onError(event);
        }
    };

    const baseColorSet: ColorShade | ThemeColors['background'] | ThemeColors['foreground'] = themeColors[color] || themeColors.default;
    const avatarBgColor = typeof baseColorSet === 'string' ? baseColorSet : baseColorSet.DEFAULT;
    const avatarFgColor = typeof baseColorSet === 'string' ? (color === 'default' && mode === 'light' ? themeColors.foreground : themeColors.background) : baseColorSet.foreground;

    const sizeMap: Record<AvatarSize, number> = {
        sm: 32,
        md: 48,
        lg: 64,
    };
    const avatarDimension = sizeMap[size];

    const radiusValue = useMemo(() => ({
        none: 0,
        sm: layoutConfig.borderRadius?.sm || 4,
        md: layoutConfig.borderRadius?.md || 8,
        lg: layoutConfig.borderRadius?.lg || 12,
        full: avatarDimension / 2, // For perfect circle
    }[radius]), [radius, avatarDimension, layoutConfig.borderRadius]);

    const initials = useMemo(() => getInitials(name), [name]);
    const displayImage = src && !imageError;

    const renderFallback = () => {
        if (!showFallback) return null;
        if (fallback) return React.cloneElement(fallback, { style: customSlotsStyles?.fallback });

        const effectiveGlassTint = glassTint || (mode === 'light' ? 'light' : 'dark');

        const fallbackContentStyle = [
            styles.fallbackBase,
            {
                width: avatarDimension,
                height: avatarDimension,
                borderRadius: radiusValue,
                backgroundColor: isGlass ? 'transparent' : avatarBgColor, // Transparent for glass
            },
            customSlotsStyles?.fallback,
        ];

        if (icon) {
            return (
                <View style={fallbackContentStyle}>
                    {isGlass && (
                        <BlurView
                            tint={effectiveGlassTint}
                            intensity={glassIntensity}
                            style={[StyleSheet.absoluteFill, { borderRadius: radiusValue, overflow: 'hidden' }]}
                            {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                        />
                    )}
                    {React.cloneElement(icon, {
                        size: avatarDimension * 0.6, // Scale icon size
                        color: avatarFgColor,
                        style: customSlotsStyles?.icon,
                    })}
                </View>
            );
        }
        if (initials) {
            const fontSize = avatarDimension * (initials.length > 1 ? 0.35 : 0.45);
            return (
                <View style={fallbackContentStyle}>
                    {isGlass && (
                        <BlurView
                            tint={effectiveGlassTint}
                            intensity={glassIntensity}
                            style={[StyleSheet.absoluteFill, { borderRadius: radiusValue, overflow: 'hidden' }]}
                            {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                        />
                    )}
                    <Text style={[styles.initialsText, { color: avatarFgColor, fontSize }, customSlotsStyles?.initials]}>
                        {initials}
                    </Text>
                </View>
            );
        }
        // Default icon fallback
        return (
            <View style={fallbackContentStyle}>
                {isGlass && (
                    <BlurView
                        tint={effectiveGlassTint}
                        intensity={glassIntensity}
                        style={[StyleSheet.absoluteFill, { borderRadius: radiusValue, overflow: 'hidden' }]}
                        {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                    />
                )}
                <AvatarIcon size={avatarDimension * 0.6} color={avatarFgColor} style={customSlotsStyles?.icon} />
            </View>
        );
    };

    // If displaying an image, glass effect is not applied directly to the image container
    // It's primarily for fallbacks.
    // The main container needs overflow: 'hidden' for children (like BlurView or Image) to be clipped by borderRadius.
    const containerStyle = [
        styles.base,
        {
            width: avatarDimension,
            height: avatarDimension,
            borderRadius: radiusValue,
        },
        isBordered && styles.bordered,
        isBordered && {
            borderColor: avatarBgColor,
        },
        isDisabled && styles.disabled,
        customSlotsStyles?.base,
        style,
    ];

    const imageStyle = [
        styles.image,
        {
            width: avatarDimension,
            height: avatarDimension,
            borderRadius: radiusValue,
        },
        customSlotsStyles?.img,
    ];

    return (
        <View style={containerStyle}>
            {displayImage ? (
                <ImgComponent
                    source={typeof src === 'string' ? { uri: src } : src as ImageSourcePropType}
                    style={imageStyle}
                    onError={handleImageError}
                    accessibilityLabel={name || 'User avatar'}
                    {...imgProps}
                />
            ) : (
                renderFallback()
            )}
        </View>
    );
};

const styles = StyleSheet.create({
    base: {
        justifyContent: 'center',
        alignItems: 'center',
        overflow: 'hidden', // Ensures border radius clips image/fallback
    },
    image: {
        // width and height set dynamically
    },
    fallbackBase: {
        justifyContent: 'center',
        alignItems: 'center',
    },
    initialsText: {
        fontWeight: 'bold',
        textAlign: 'center',
    },
    bordered: {
        padding: 2,
        borderWidth: 2 // Adjust as needed
    },
    disabled: {
        opacity: 0.5, // Use layoutConfig.disabledOpacity
    },
});

export default Avatar;