import { Text, useTheme, } from '@crossbuildui/core'; // Adjust path
import { BlurView } from 'expo-blur';
import React, { Children, isValidElement, useMemo } from 'react';
import { Platform, StyleProp, StyleSheet, View, ViewStyle } from 'react-native';
import { AvatarGroupContext } from './AvatarGroupContext';
import type { AvatarGroupContextProps, AvatarGroupProps, AvatarProps, AvatarSize } from './types';

const AvatarGroup: React.FC<AvatarGroupProps> = ({
    children,
    max = 5,
    total,
    size = 'md', // Default size for the count if not overridden by context
    color = 'default',
    radius = 'full',
    isBordered = true, // Avatars in a group usually have borders
    isDisabled = false,
    isGrid = false, // Not fully implemented in this basic version, affects spacing
    renderCount,
    isGlass = false, // Propagate to context
    glassTint,
    glassIntensity = 50,
    style,
    countStyles,
}) => {
    const { colors: themeColors, layout: layoutConfig, mode } = useTheme();

    const contextValue: AvatarGroupContextProps = useMemo(() => ({
        size,
        color,
        radius,
        isBordered,
        isDisabled,
        isGlass,
        glassTint,
        glassIntensity,
    }), [size, color, radius, isBordered, isDisabled, isGlass, glassTint, glassIntensity]);

    const validAvatars = Children.toArray(children).filter(child =>
        isValidElement<AvatarProps>(child)
    ) as React.ReactElement<AvatarProps>[];

    const visibleAvatars = validAvatars.slice(0, max);
    const hiddenCount = total !== undefined ? Math.max(0, total - max) : Math.max(0, validAvatars.length - max);

    const sizeMap: Record<AvatarSize, number> = {
        sm: 32,
        md: 48,
        lg: 64,
    };
    const avatarDimension = sizeMap[size || 'md']; // Fallback to 'md' if size is undefined
    const overlap = avatarDimension * (isGrid ? 0.1 : 0.35); // Adjust overlap

    const containerStyle: StyleProp<ViewStyle> = [
        styles.base,
        isGrid && styles.grid,
        style,
    ];

    const renderCountComponent = () => {
        if (hiddenCount <= 0) return null;
        if (renderCount) return renderCount(hiddenCount);

        const countBaseColorSet = themeColors[color] || themeColors.default;
        const countBgColor = isGlass ? 'transparent' : (typeof countBaseColorSet === 'string' ? themeColors.content1.DEFAULT : countBaseColorSet['200']);
        const countFgColor = isGlass ? themeColors.foreground : (typeof countBaseColorSet === 'string' ? themeColors.foreground : countBaseColorSet.foreground);
        const effectiveGlassTint = glassTint || (mode === 'light' ? 'light' : 'dark');

        return (
            <View
                style={[
                    styles.countAvatar,
                    {
                        width: avatarDimension,
                        height: avatarDimension,
                        borderRadius: radius === 'full' ? avatarDimension / 2 : layoutConfig.borderRadius?.full || avatarDimension / 2,
                        backgroundColor: countBgColor,
                        marginLeft: -overlap,
                        zIndex: 999,
                        overflow: 'hidden', // For BlurView clipping
                    },
                    isBordered && styles.borderedCount,
                    isBordered && !isGlass && { borderColor: typeof countBaseColorSet === 'string' ? countBaseColorSet : countBaseColorSet.DEFAULT },
                    isBordered && isGlass && { borderColor: 'transparent' }, // Border might look odd with glass, or use a translucent one
                    countStyles?.base,
                ]}
            >
                {isGlass && (
                    <BlurView
                        tint={effectiveGlassTint}
                        intensity={glassIntensity}
                        style={[StyleSheet.absoluteFill, { borderRadius: radius === 'full' ? avatarDimension / 2 : layoutConfig.borderRadius?.full || avatarDimension / 2 }]}
                        {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                    />
                )}
                <Text style={[styles.countText, { color: countFgColor, fontSize: avatarDimension * 0.4 }, countStyles?.text]}>
                    +{hiddenCount}
                </Text>
            </View>
        );
    };

    return (
        <AvatarGroupContext.Provider value={contextValue}>
            <View style={containerStyle}>
                {visibleAvatars.map((avatar, index) =>
                    React.cloneElement(avatar, {
                        key: `avatar-${index}`,
                        style: [
                            avatar.props.style,
                            index > 0 && { marginLeft: -overlap }, // Apply overlap
                            { zIndex: index + 1 }, // Stacking order
                        ],
                    })
                )}
                {renderCountComponent()}
            </View>
        </AvatarGroupContext.Provider>
    );
};

const styles = StyleSheet.create({
    base: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    grid: {
        // Add styles for grid layout if needed, e.g., flexWrap: 'wrap'
    },
    countAvatar: {
        justifyContent: 'center',
        alignItems: 'center',
    },
    borderedCount: {
        borderWidth: 2,
    },
    countText: {
        fontWeight: 'bold',
    },
});

export default AvatarGroup;